files['src/lib/managerDemoStore.js']=r'''import {useSyncExternalStore} from 'react';
import {assignedFacility,managerPermissions,managerSeed} from '@/mocks/managerData';
export const managerDemoEnabled=import.meta.env.VITE_USE_MOCK!=='false';
export const managerStorageKey='VaultSpace_manager_priority2_demo_v1';
const clone=value=>JSON.parse(JSON.stringify(value));
const empty=Object.fromEntries(Object.keys(managerSeed).map(key=>[key,[]]));
function scope(value){return Object.fromEntries(Object.keys(managerSeed).map(key=>[key,Array.isArray(value?.[key])?value[key].filter(row=>row.facilityId===assignedFacility.id):clone(managerSeed[key])]));}
let state;
try{state=managerDemoEnabled?scope(JSON.parse(localStorage.getItem(managerStorageKey))||managerSeed):clone(empty);}catch{state=managerDemoEnabled?clone(managerSeed):clone(empty);}
const listeners=new Set();
const notify=()=>listeners.forEach(fn=>fn());
window.addEventListener('storage',event=>{if(event.key===managerStorageKey&&managerDemoEnabled){try{state=scope(event.newValue?JSON.parse(event.newValue):managerSeed);notify();}catch{/* Retain the last valid demo state. */}}});
export function useManagerData(){return useSyncExternalStore(fn=>{listeners.add(fn);return()=>listeners.delete(fn);},()=>state);}
export function money(value){return new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(value||0);}
export function customerName(data,id){return data.customers.find(row=>row.id===id)?.name||id||'—';}
export function unitCode(data,id){return data.units.find(row=>row.id===id)?.code||'—';}
export function resourceName(data,type,id){const collection={'Storage Unit':'units',Zone:'zones',Rack:'racks',Shelf:'shelves'}[type];return data[collection]?.find(row=>row.id===id)?.code||'Unavailable resource';}
export function capacity(data){const active=data.shelves.filter(row=>row.status==='ACTIVE');return {max:active.reduce((s,r)=>s+r.max_volume_m3,0),used:active.reduce((s,r)=>s+r.used_volume_m3,0),allocated:data.rentals.filter(r=>r.service==='MANAGED_INVENTORY'&&['ACTIVE','OVERDUE'].includes(r.status)).reduce((s,r)=>s+r.allocated_capacity_m3,0)};}
export function availability(data,reservation){if(reservation.service==='SELF_STORAGE'){const unit=data.units.find(r=>r.id===reservation.unitId);const conflict=data.reservations.some(r=>r.id!==reservation.id&&r.status==='APPROVED'&&r.unitId===reservation.unitId&&r.start<=reservation.end&&r.end>=reservation.start);return unit?.status==='AVAILABLE'&&unit.maintenance==='CLEAR'&&!conflict;}
 const c=capacity(data);const pending=data.reservations.filter(r=>r.id!==reservation.id&&r.service==='MANAGED_INVENTORY'&&r.status==='APPROVED').reduce((s,r)=>s+r.allocated_capacity_m3,0);return reservation.allocated_capacity_m3>0&&c.allocated+pending+reservation.allocated_capacity_m3<=c.max;}
export function extensionQuote(data,request){const rental=data.rentals.find(r=>r.id===request.rentalId);if(!rental)return {available:false,charge:0,label:'Rental unavailable'};
 if(request.kind==='CAPACITY'){const c=capacity(data);const delta=request.requested_capacity_m3-rental.allocated_capacity_m3;const reserved=data.reservations.filter(r=>r.service==='MANAGED_INVENTORY'&&r.status==='APPROVED').reduce((s,r)=>s+r.allocated_capacity_m3,0);return {available:rental.status==='ACTIVE'&&rental.service==='MANAGED_INVENTORY'&&delta>0&&c.allocated+reserved+delta<=c.max,charge:Math.max(0,delta)*200000*request.months,label:`${rental.allocated_capacity_m3} → ${request.requested_capacity_m3} m³`,formula:`${Math.max(0,delta)} m³ × ${money(200000)} × ${request.months} month(s)`};}
 const end=new Date(rental.end+'T12:00:00');end.setMonth(end.getMonth()+request.months);const newEnd=end.toLocaleDateString('en-CA');const blocked=rental.service==='SELF_STORAGE'&&data.reservations.some(r=>r.status==='APPROVED'&&r.unitId===rental.unitId&&r.start>rental.end&&r.start<=newEnd);return {available:rental.status==='ACTIVE'&&!blocked,charge:rental.monthly*request.months,label:`${rental.end} → ${newEnd}`,newEnd,formula:`${money(rental.monthly)} × ${request.months} month(s)`};}
export function refundQuote(data,refund){const payment=data.payments.find(p=>p.id===refund.paymentId);return Math.min(payment?.amount||0,Math.round((payment?.amount||0)*refund.unusedDays/refund.periodDays));}
function change(permission,fn){if(!managerDemoEnabled)throw Error('Manager API is not connected. Preview actions are disabled.');if(!managerPermissions[permission])throw Error('You do not have permission for this action.');const next=clone(state);fn(next);localStorage.setItem(managerStorageKey,JSON.stringify(next));state=next;notify();}
function get(data,collection,id){const row=data[collection]?.find(row=>row.id===id&&row.facilityId===assignedFacility.id);if(!row)throw Error('Record unavailable in your assigned facility.');return row;}
function timeline(row,status,note){row.status=status;row.timeline=[...(row.timeline||[]),{at:new Date().toISOString(),status,note}];}
export function decide(collection,id,decision,reason=''){const permission={reservations:'approveReservations',extensions:'approveExtensions',refunds:'approveRefunds'}[collection];if(!permission||!['APPROVED','REJECTED'].includes(decision))throw Error('Unsupported decision.');if(decision==='REJECTED'&&!reason.trim())throw Error('A rejection reason is required.');change(permission,data=>{const row=get(data,collection,id);if(row.status!=='PENDING')throw Error('This request has already been reviewed.');if(decision==='APPROVED'){
 if(collection==='reservations'&&!availability(data,row))throw Error('The selected unit or capacity is unavailable.');
 if(collection==='extensions'){const quote=extensionQuote(data,row);if(!quote.available)throw Error('This extension is unavailable.');row.calculatedCharge=quote.charge;const rental=get(data,'rentals',row.rentalId);if(row.kind==='TIME')rental.end=quote.newEnd;else rental.allocated_capacity_m3=row.requested_capacity_m3;data.charges.unshift({id:'CHG-'+crypto.randomUUID(),facilityId:assignedFacility.id,customerId:rental.customerId,rentalId:rental.id,reason:'Approved rental extension',amount:quote.charge,status:'PENDING',date:new Date().toLocaleDateString('en-CA'),policy:quote.formula});}
 if(collection==='refunds'){const payment=get(data,'payments',row.paymentId);if(payment.status!=='PAID')throw Error('Refund requires an original paid payment.');row.calculatedRefund=refundQuote(data,row);}
 }timeline(row,decision,decision==='REJECTED'?reason.trim():'Approved by the facility manager (demo).');});}
export function verifyCustomer(id,status,note){if(!['VERIFIED','REJECTED'].includes(status)||!note.trim())throw Error('Verification decision and review notes are required.');change('verifyCustomers',data=>{const row=get(data,'customers',id);row.verification=status;row.verificationNote=note.trim();row.verifiedAt=new Date().toISOString();});}
export function saveUnit(id,values){change('manageUnits',data=>{if(!values.code.trim()||!values.pricingReference.trim()||!['Small','Medium','Large'].includes(values.size)||!['AVAILABLE','MAINTENANCE','UNAVAILABLE','OCCUPIED'].includes(values.status)||!Number.isFinite(Number(values.price))||Number(values.price)<=0)throw Error('Enter a code, supported size, positive price and pricing reference.');if(data.units.some(r=>r.id!==id&&r.code.toLowerCase()===values.code.trim().toLowerCase()))throw Error('Unit code already exists.');const existing=id?get(data,'units',id):null;if(existing?.rentalId&&(values.status!=='OCCUPIED'||values.size!==existing.size))throw Error('An occupied unit must retain its status and size.');if(!existing?.rentalId&&values.status==='OCCUPIED')throw Error('A unit cannot be occupied without a rental.');const approved=data.reservations.some(r=>r.unitId===id&&r.status==='APPROVED');if(approved&&(values.status!=='AVAILABLE'||values.size!==existing.size))throw Error('An approved reservation protects this unit’s availability and size.');const row={...existing,...values,code:values.code.trim(),price:Number(values.price),facilityId:assignedFacility.id,id:id||'UNIT-'+crypto.randomUUID(),rentalId:existing?.rentalId||null,maintenance:values.status==='MAINTENANCE'?'OPEN':existing?.maintenance==='OPEN'?'OPEN':'CLEAR'};if(existing)Object.assign(existing,row);else data.units.unshift(row);});}
export function assignTask(id,staffId){change('assignTasks',data=>{const task=get(data,'tasks',id),staff=get(data,'staff',staffId);if(['COMPLETED','CANCELLED'].includes(task.status))throw Error('Closed tasks cannot be reassigned.');if(!staff.types.includes(task.type))throw Error('This staff member is not qualified for the task type.');task.staffId=staffId;timeline(task,task.status,`Assigned to ${staff.name}.`);});}
export function updateMaintenance(id,status,staffId,notes){change('manageMaintenance',data=>{const row=get(data,'maintenance',id);if(!['OPEN','IN_PROGRESS','RESOLVED'].includes(status)||!notes.trim())throw Error('Select a valid status and enter operational notes.');if(row.status==='RESOLVED')throw Error('This issue is already resolved.');if(staffId){const staff=get(data,'staff',staffId);if(!staff.types.includes('MAINTENANCE'))throw Error('Select maintenance staff.');}if(status!=='OPEN'&&!staffId)throw Error('Assign maintenance staff before progressing the issue.');row.staffId=staffId||null;row.notes=notes.trim();timeline(row,status,notes.trim());});}
export function updateSupport(id,{status,staffId,response,notes}){change('manageSupport',data=>{const row=get(data,'support',id);if(row.status==='RESOLVED')throw Error('This ticket is already resolved.');if(!['OPEN','IN_PROGRESS','RESOLVED'].includes(status))throw Error('Select a valid support status.');if(staffId){const staff=get(data,'staff',staffId);if(!staff.types.includes('SUPPORT'))throw Error('Select customer service staff.');}if(status!=='OPEN'&&!staffId)throw Error('Assign support staff first.');if(status==='RESOLVED'&&!notes.trim())throw Error('Resolution notes are required.');if(!response.trim()&&!notes.trim()&&row.staffId===staffId&&row.status===status)throw Error('Enter a response or update the ticket.');row.staffId=staffId||null;row.notes=notes.trim();if(response.trim())row.messages.push({at:new Date().toISOString(),author:assignedFacility.manager,text:response.trim()});timeline(row,status,notes.trim()||'Support assignment / response updated.');});}
export function updateOperation(id,{status,notes,checks}){change('manageOperations',data=>{const row=get(data,'tasks',id);if(!['PENDING','IN_PROGRESS'].includes(row.status)||!['IN_PROGRESS','COMPLETED'].includes(status))throw Error('Unsupported operation transition.');if(!row.staffId)throw Error('Assign a qualified staff member first.');if(!notes.trim())throw Error('Operational notes are required.');if(status==='COMPLETED'&&checks.some(value=>!value))throw Error('Complete every inspection / operation checklist item first.');timeline(row,status,notes.trim());row.notes=notes.trim();});}
'''
for name,content in files.items():
 p=Path(name);p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content,encoding='utf-8')
